sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float radius;
uniform float brightness;
layout(color) uniform half4 color;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float d = distance(coord, center * size) / max(radius * max(size.x, size.y), 0.0001);
    float light = brightness * (exp(-d * d * 6) + 0.35 * exp(-(d - 1) * (d - 1) * 60));
    half3 rgb = c.rgb + color.rgb * half(light);
    return half4(rgb, max(c.a, max(rgb.r, max(rgb.g, rgb.b))));
}
